import type { CatalogEntry, CatalogTier } from "./types";

/**
 * Every picture the shop owns, with the words people type for it.
 *
 * To add a picture: put /images/catalog/<key>.webp in public/, then add ONE row below.
 *  - keywords: lowercase, singular, how people really say it (slang, trade names, spellings).
 *    Spacing, hyphens, plurals and one-letter typos are handled for you.
 *  - tier: 1 whole device, 2 broad category, 3 specific item or part (more specific wins).
 *  - excludes: words that mean "not this" (a "port" or "flex" is never a cable).
 *  - devices: device families this belongs to; a name that mentions another device never gets it.
 *
 * Keep ONE word for ONE job: if two rows at the same tier own the same phrase, the name is
 * ambiguous and gets no picture (a plain "speaker" is that on purpose, see tests/catalog-match.test.ts).
 */

